#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,requests
ROOT=Path('/home/ubuntu/CHAOS'); RAW=ROOT/'campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/raw/worldbank_country_metadata_v2'; RAW.mkdir(parents=True,exist_ok=True); url='https://api.worldbank.org/v2/country?format=json&per_page=400'; r=requests.get(url,timeout=120,headers={'User-Agent':'CHAOS-research-metadata/2.0','Accept':'application/json'}); b=r.content; raw=RAW/'worldbank_country_metadata.json'; raw.write_bytes(b); now=datetime.now(timezone.utc).isoformat(); (RAW/'request.url.txt').write_text(url+'\n'); (RAW/'response.headers.json').write_text(json.dumps({'status_code':r.status_code,'content_type':r.headers.get('content-type'),'content_length':r.headers.get('content-length'),'retrieved_at_utc':now,'url':r.url},ensure_ascii=False,indent=2)+'\n'); d=json.loads(b); rows=d[1] if isinstance(d,list) and len(d)>1 else []; out={'source':'World Bank Country API','url':url,'retrieved_at_utc':now,'status_code':r.status_code,'raw_path':str(raw.relative_to(ROOT)),'raw_sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b),'rows':len(rows),'has_region_fields':bool(rows and 'region' in rows[0]),'status':'downloaded' if r.ok and rows else 'failed'}; (ROOT/'campaigns/research_rounds/20260827_BROWSER_DEEP_RESEARCH/WORLD_BANK_COUNTRY_METADATA_ACQUISITION_V2.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n'); print(json.dumps(out,ensure_ascii=False,indent=2))
